/** ZIP downloads stay local. Entry names are generated by Terrier, never taken as paths from an upload. */
import {zipSync,strToU8} from 'fflate';
import type {Zippable} from 'fflate';

export interface ZipEntry{name:string;data:string|Uint8Array}
const MAX_ARCHIVE_BYTES=256*1024*1024;
const MAX_ARCHIVE_FILES=65000; // Standard ZIP directory counts; this writer does not emit ZIP64 directories.
export function checkZipFileCount(count:number):void{
  if(count>MAX_ARCHIVE_FILES)throw new Error('This ZIP exceeds 65,000 files. Increase the doors per list or export a smaller selection.');
}

/** Enforce the memory budget while documents are produced, before retaining a large bundle. */
export class ZipBundle{
  private entries:ZipEntry[]=[];private bytes=0;
  add(entry:ZipEntry):void{
    checkZipFileCount(this.entries.length+1);
    const size=typeof entry.data==='string'?strToU8(entry.data).byteLength:entry.data.byteLength;
    if(this.bytes+size>MAX_ARCHIVE_BYTES)throw new Error('This ZIP exceeds 256 MB. Export a smaller selection.');
    this.bytes+=size;this.entries.push(entry);
  }
  build():Uint8Array<ArrayBuffer>{return buildZip(this.entries);}
}

export function buildZip(entries:ZipEntry[]):Uint8Array<ArrayBuffer>{
  checkZipFileCount(entries.length);
  const files:Zippable=Object.create(null);let total=0;
  for(const {name,data} of entries){
    if(!name||name.startsWith('/')||name.includes('\\')||name.includes(':')||name.split('/').some(p=>!p||p==='.'||p==='..')||/[\x00-\x1f]/.test(name))throw new Error('Invalid ZIP entry name.');
    if(Object.hasOwn(files,name))throw new Error('Duplicate ZIP entry name.');
    const bytes=typeof data==='string'?strToU8(data):data;
    total+=bytes.byteLength;
    if(total>MAX_ARCHIVE_BYTES)throw new Error('This ZIP exceeds 256 MB. Export a smaller selection.');
    // PDFs already contain compressed streams; storing them avoids redundant work on the UI thread.
    files[name]=[bytes,{level:name.endsWith('.pdf')?0:1}];
  }
  return zipSync(files);
}

export function downloadZip(name:string,bytes:Uint8Array<ArrayBuffer>):void{
  const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));
  const link=document.createElement('a');link.href=url;link.download=name;link.click();
  setTimeout(()=>URL.revokeObjectURL(url),60000);
}

export const listFileStem=(index:number):string=>`list-${String(index+1).padStart(3,'0')}`;
/** Let the loading state paint between individual documents. */
export const yieldExport=():Promise<void>=>new Promise(resolve=>setTimeout(resolve,0));
